+static String get_format_name(FourCharCode fourcc) {
+	switch (fourcc) {
+		// 8-bit YCbCr 4:2:0
+		case kCVPixelFormatType_420YpCbCr8BiPlanarFullRange:
+			return "YCbCr_420_Full";
+		case kCVPixelFormatType_420YpCbCr8BiPlanarVideoRange:
+			return "YCbCr_420_Video";
+		// 8-bit YCbCr 4:2:2
+		case kCVPixelFormatType_422YpCbCr8BiPlanarFullRange:
+			return "YCbCr_422_Full";
+		case kCVPixelFormatType_422YpCbCr8BiPlanarVideoRange:
+			return "YCbCr_422_Video";
+		// RGB/BGRA
+		case kCVPixelFormatType_32BGRA:
+			return "BGRA_8888";
+		case kCVPixelFormatType_32RGBA:
+			return "RGBA_8888";
+		default:
+			// Return FourCC string for unknown formats.
+			return String::chr((char)(fourcc >> 24) & 0xFF) +
+					String::chr((char)(fourcc >> 16) & 0xFF) +
+					String::chr((char)(fourcc >> 8) & 0xFF) +
+					String::chr((char)(fourcc >> 0) & 0xFF);
+	}
+}
+
 Array CameraFeedMacOS::get_formats() const {
 	Array result;
+	int format_index = 0;
 	for (AVCaptureDeviceFormat *format in device.formats) {
-		Dictionary dictionary;
 		CMFormatDescriptionRef formatDescription = format.formatDescription;
 		CMVideoDimensions dimension = CMVideoFormatDescriptionGetDimensions(formatDescription);
-		dictionary["width"] = dimension.width;
-		dictionary["height"] = dimension.height;
 		FourCharCode fourcc = CMFormatDescriptionGetMediaSubType(formatDescription);
-		dictionary["format"] =
-				String::chr((char)(fourcc >> 24) & 0xFF) +
-				String::chr((char)(fourcc >> 16) & 0xFF) +
-				String::chr((char)(fourcc >> 8) & 0xFF) +
-				String::chr((char)(fourcc >> 0) & 0xFF);
-		result.push_back(dictionary);
+
+		// Create an entry for each supported frame rate range.
+		for (AVFrameRateRange *range in format.videoSupportedFrameRateRanges) {
+			Dictionary dictionary;
+			dictionary["width"] = dimension.width;
+			dictionary["height"] = dimension.height;
+			dictionary["format"] = get_format_name(fourcc);
+			dictionary["format_index"] = format_index;
+
+			// Convert CMTime to frame rate.
+			// minFrameDuration corresponds to the maximum frame rate.
+			CMTime duration = range.minFrameDuration;
+			if (duration.value > 0) {
+				dictionary["frame_numerator"] = (int)duration.timescale;
+				dictionary["frame_denominator"] = (int)duration.value;
+			} else {
+				dictionary["frame_numerator"] = 0;
+				dictionary["frame_denominator"] = 1;
+			}
+
+			result.push_back(dictionary);
+		}
+		format_index++;
 	}
 	return result;
 }
```
